var MAXPOINTS = 20000; // Dial this back if too slow.

var n = 7;
var m = 3;
var maxHarmonics = 15;
var myPoints = [];
var cycleMillis = 12 * 1000;
var lastChange = -cycleMillis;
var lastc;
var c;

//
//  In the Begining.....
//
function setup() {
	createCanvas(max(windowWidth, windowHeight), max(windowWidth, windowHeight)); // There was nothing but the void.....
	pixelDensity(1);
	background(0); // Only darkness....
	colorMode(HSB);
	c = color(n * 360 / maxHarmonics, 50 + m * 50 / maxHarmonics, 100); // And then came light.....
	lastc = c;
	smooth();
	let pointCount = constrain((width * height) / 200, 2000, MAXPOINTS); // And the many points of light were created.....
	for (i = 0; i < pointCount; i++) {
		myPoints.push(new Speck()); // Spread throughout the void.....
	}
	shuff();
}

//
//  And at every point in time thereafter.....
//
function draw() {
	translate(width / 2, height / 2);
	scale(0.95 * width / 2, 0.95 * height / 2); // The void was given width and breadth.....

	background(0, 0, 0, 0.2);

	if (millis() > lastChange + cycleMillis) { // And every new day....
		shuff(); // A new pattern was given form.....
	}

	noFill();
	strokeWeight(6 / max(width, height));
	colorMode(RGB);
	stroke(lerpColor(lastc, c, map(millis() - lastChange, 0, 1000, 0, 1))); // Softly shifting from the last.....
	colorMode(HSB);

	for (i = 0; i < myPoints.length; i++) { // Each point of light found its place.
		myPoints[i].move();
		myPoints[i].display();
	}

}

//
//  A new pattern is born.
//
function shuff() {
	lastChange = millis();
	n = floor(random(maxHarmonics));
	m = floor(random(maxHarmonics));
	let _wG_1 = 0; while ((m == n) && ++_wG_1 < 20000) {
		m = floor(random(maxHarmonics));
	}
	for (i = 0; i < myPoints.length; i += 2) { // Every other point of light found a new place.....
		myPoints[i].randomize();
	}
	lastc = c;
	c = color(n * 360 / maxHarmonics, 50 + m * 50 / maxHarmonics, 100); // With colour.....
}

//
//  Defining the sound of silence.
//
function chladni(x, y) { //-1..1, -1..1
	let L = 2;
	return cos(n * PI * x / L) * cos(m * PI * y / L) - cos(m * PI * x / L) * cos(n * PI * y / L);
}

//
//  Every speck of light.
//
class Speck {
	constructor() {
		this.randomize();
		this.speed = 0.035; // magic number
	}

	randomize() {
		this.x = random(-1, 1);
		this.y = random(-1, 1);
	}

	move() {
		let jigglemax = 0.003; // magic number
		let jiggleX = random(-jigglemax, jigglemax);
		let jiggleY = random(-jigglemax, jigglemax);

		let amount = chladni(this.x, this.y);

		if (amount >= 0) { // If Positive
			if (chladni(this.x + jigglemax, this.y) >= amount) {
				this.x = constrain(this.x - random(-0.5, 1) * amount * this.speed + jiggleX, -1, 1);
			} else {
				this.x = constrain(this.x + random(-0.5, 1) * amount * this.speed + jiggleX, -1, 1);
			}
			if (chladni(this.x, this.y + jigglemax) >= amount) {
				this.y = constrain(this.y - random(-0.5, 1) * amount * this.speed + jiggleY, -1, 1);
			} else {
				this.y = constrain(this.y + random(-0.5, 1) * amount * this.speed + jiggleY, -1, 1);
			}
		} else { // If Negative
			if (chladni(this.x + jigglemax, this.y) <= amount) {
				this.x = constrain(this.x + random(-0.5, 1) * amount * this.speed + jiggleX, -1, 1);
			} else {
				this.x = constrain(this.x - random(-0.5, 1) * amount * this.speed + jiggleX, -1, 1);
			}
			if (chladni(this.x, this.y + jigglemax) <= amount) {
				this.y = constrain(this.y + random(-0.5, 1) * amount * this.speed + jiggleY, -1, 1);
			} else {
				this.y = constrain(this.y - random(-0.5, 1) * amount * this.speed + jiggleY, -1, 1);
			}
		}
	}

	display() {
		point(this.x, this.y);
	}
}

//disable default right mouse click
document.addEventListener("contextmenu", (event) => event.preventDefault(), "true")

//left click restarts, right click does an image capture
var lapse = 0; // mouse timer
function mousePressed() {
	if (millis() - lapse > 400) {
		lapse = millis();
		if (mouseButton === RIGHT) {
			save("img_" + nf(year(), 4) + nf(month(), 2) + nf(day(), 2) + '_' + nf(hour(), 2) + nf(minute(), 2) + nf(second(), 2) + ".jpg");
		} else if (mouseButton === CENTER) {} else {
			shuff();
		}
	}
	return (false)
}
